    let config_dir = get_config_dir();
    fs::create_dir_all(&config_dir)?;
    let config_path = config_dir.join("config.json");
    let content = format!("{{\"repo\":\"{}\"}}", repo_path);
    fs::write(config_path, content)
}

fn clear_config() {
    let config_path = get_config_path();
    if config_path.exists() {
        let _ = fs::remove_file(config_path);
    }
}

fn print_error(msg: &str) {
    eprintln!(" ERROR eureka > {}", msg);
}

fn prompt_input(label: &str) -> Option<String> {
    let stdout = io::stdout();
    let stdin = io::stdin();

    loop {
        {
            let mut handle = stdout.lock();
            write!(handle, "{}{}{}{}\n{}> ", RESET, BOLD, GREEN, label, RESET).unwrap();
            handle.flush().unwrap();
        }

        let mut line = String::new();
        match stdin.lock().read_line(&mut line) {
            Ok(0) => return None, // EOF
            Ok(_) => {
                let value = line.trim().to_string();
                if !value.is_empty() {
                    return Some(value);
                }
            }
            Err(_) => return None,
        }
    }
}

fn get_editor() -> String {
    env::var("EDITOR")
        .or_else(|_| env::var("VISUAL"))
        .unwrap_or_else(|_| "vi".to_string())
}

/// Try to open the editor. Returns None on success, Some(error_message) on failure.
/// The editor's exit code is ignored; only OS-level errors are reported.
fn try_open_editor(filepath: &Path) -> Option<String> {
    let editor = get_editor();
    let parts: Vec<&str> = editor.split_whitespace().collect();
    if parts.is_empty() {
        return Some("cannot find binary path".to_string());
    }

    let mut cmd = process::Command::new(parts[0]);
    cmd.args(&parts[1..]);
    cmd.arg(filepath);

    match cmd.status() {
        Ok(_) => None, // Success (exit code ignored)
        Err(e) => {
            let msg = format!("{} (os error {})", e, e.raw_os_error().unwrap_or(0));
            Some(msg)
        }
    }
}

fn git_run(repo_path: &Path, args: &[&str]) -> (bool, String, String) {
    let output = process::Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .args(args)
        .output();

    match output {
        Ok(out) => {
            let stdout = String::from_utf8_lossy(&out.stdout).to_string();
            let stderr = String::from_utf8_lossy(&out.stderr).to_string();
            (out.status.success(), stdout, stderr)
        }
        Err(e) => (false, String::new(), e.to_string()),
    }
}

fn first_time_setup() {
    print!("{}{}", RESET, YELLOW);
    println!("############################################################");
    println!("####                  First Time Setup                  ####");
    println!("############################################################");
    println!();
    println!("This tool requires you to have a repository with a README.md");
    println!("in the root folder. The markdown file is where your ideas");
    println!("will be stored.");
    println!();
    println!("Once first time setup has completed, simply run Eureka again");
    println!("to begin writing down ideas.");
    println!("        ");
    print!("{}", RESET);
    io::stdout().flush().unwrap();

    if let Some(repo_path) = prompt_input("Absolute path to your idea repo") {
        match save_config(&repo_path) {
            Ok(_) => println!("First time setup complete. Happy ideation!"),
            Err(e) => print_error(&e.to_string()),
        }
    }
}

fn format_checkout_conflict_error(conflict_count: usize) -> String {
    if conflict_count == 1 {
        "1 conflict prevents checkout; class=Checkout (20); code=Conflict (-13)".to_string()
    } else {
        format!(
            "{} conflicts prevent checkout; class=Checkout (20); code=Conflict (-13)",
            conflict_count
        )
    }
}

fn add_idea(repo_path: &str) {
    // Step 1: Get idea summary
    let summary = match prompt_input(">> Idea summary") {
        Some(s) => s,
        None => return,
    };

    let readme_path = Path::new(repo_path).join("README.md");

    // Step 2: Open editor (if README.md exists)
    // The editor error is deferred - we continue with git ops even if editor fails
    let editor_error = if readme_path.exists() {
        try_open_editor(&readme_path)
    } else {
        None // README doesn't exist, no editor
    };

    // Step 3: Print "Adding and committing..."
    println!("Adding and committing your new idea to main..");

    // Step 4: Check if README.md exists (for git add)
    if !readme_path.exists() {
        print_error("No such file or directory (os error 2)");
        return;
    }

    // Step 5: Git operations

    // Check if main branch exists
    let (main_exists, _, _) = git_run(Path::new(repo_path), &["rev-parse", "--verify", "main"]);

    if main_exists {
        // Checkout to main
        let (success, _, stderr) = git_run(Path::new(repo_path), &["checkout", "main"]);
        if !success {
            // Format conflict error similar to libgit2
            if stderr.contains("would be overwritten") {
                let conflict_count = stderr.lines()
                    .filter(|l| l.starts_with('\t'))
                    .count()
                    .max(1);
                print_error(&format_checkout_conflict_error(conflict_count));
            } else {
                print_error(stderr.trim());
            }
            // Still print deferred editor error if any
            if let Some(err) = editor_error {
                print_error(&err);
            }
            return;
        }
    } else {
        // Create main branch from HEAD
        let (success, _, stderr) = git_run(Path::new(repo_path), &["checkout", "-b", "main"]);
        if !success {
            print_error(stderr.trim());
            if let Some(err) = editor_error {
                print_error(&err);
            }
            return;
        }
    }

    // Stage README.md
    let (success, _, stderr) = git_run(Path::new(repo_path), &["add", "README.md"]);
    if !success {
        print_error(stderr.trim());
        if let Some(err) = editor_error {
            print_error(&err);
        }
        return;
    }

    // Commit (allow empty in case editor didn't modify README.md)
    let (success, _, stderr) = git_run(Path::new(repo_path), 
        &["commit", "--allow-empty", "-m", &summary]);
    if !success {
        print_error(stderr.trim());
        if let Some(err) = editor_error {
            print_error(&err);
        }
        return;
    }

    println!("Added and committed!");
    println!("Pushing your new idea..");

    // Push to origin/main
    let (success, _, stderr) = git_run(Path::new(repo_path), &["push", "origin", "main"]);
    if !success {
        if stderr.contains("does not appear to be a git repository") ||
           stderr.contains("not found") {
            print_error("remote 'origin' does not exist; class=Config (7); code=NotFound (-3)");
        } else {
            print_error(stderr.trim());
        }
        if let Some(err) = editor_error {
            print_error(&err);
        }
        return;
    }

    println!("Pushed!");

    // Print any deferred editor error
    if let Some(err) = editor_error {
        print_error(&err);
    }
}

fn view_ideas(repo_path: &str) {
    let readme_path = Path::new(repo_path).join("README.md");
    let pager = env::var("PAGER").unwrap_or_else(|_| "less".to_string());

    let status = process::Command::new(&pager)
        .arg(&readme_path)
        .status();

    if status.is_err() {
        let _ = process::Command::new("less")
            .arg(&readme_path)
            .status();
    }
}

fn get_binary_name() -> String {
    env::args().next()
        .and_then(|s| {
            Path::new(&s).file_name()
                .and_then(|n| n.to_str())
                .map(|s| s.to_string())
        })
        .unwrap_or_else(|| "eureka".to_string())
}

fn print_help() {
    let name = get_binary_name();
    println!("Input and store your ideas without leaving the terminal");
    println!();
    println!("Usage: {} [OPTIONS]", name);
    println!();
    println!("Options:");
    println!("      --clear-config  Clear your stored configuration");
    println!("  -v, --view          View ideas with your $PAGER env variable. If unset use less");
    println!("  -h, --help          Print help");
    println!("  -V, --version       Print version");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut clear_config_flag = false;
    let mut view_flag = false;
    let mut help_flag = false;
    let mut version_flag = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--clear-config" => clear_config_flag = true,
            "-v" | "--view" => view_flag = true,
            "-h" | "--help" => help_flag = true,
            "-V" | "--version" => version_flag = true,
            arg => {
                eprintln!("error: unexpected argument '{}' found", arg);
                eprintln!();
                eprintln!("Usage: {} [OPTIONS]", get_binary_name());
                eprintln!();
                eprintln!("For more information, try '--help'.");
                process::exit(2);
            }
        }
        i += 1;
    }

    if help_flag {
        print_help();
        return;
    }

    if version_flag {
        println!("eureka 2.0.0");
        return;
    }

    if clear_config_flag {
        clear_config();
        return;
    }

    match load_config() {
        None => first_time_setup(),
        Some(repo_path) => {
            if view_flag {
                view_ideas(&repo_path);
            } else {
                add_idea(&repo_path);
            }
        }
    }
}
